// Decides what to write, having read the roster as it stands.
//
// The dashboard has already checked the shape of the request -- a name that is
// not blank, a four-digit PIN. What it cannot check is the sheet at the moment
// of writing: whether the PIN is now somebody else's, whether another admin
// took that id a second ago. Those checks live here, where the rows are in hand.
const body = $('Roster Webhook').first().json.body || {};
const rows = $('Read Roster').first().json.values || [];

// Row 1 is the header. Index 0 of this array is therefore sheet row 2.
const data = rows.slice(1);

const base = 'https://sheets.googleapis.com/v4/spreadsheets/YOUR_SPREADSHEET_ID/values/';
const range = (r) => encodeURIComponent('Employees!' + r);

const norm = (v) => String(v == null ? '' : v).trim().toLowerCase();

// Ids are compared as numbers: the clock pads them ('3' and '003' are the same
// person), and a cell Sheets has turned into the number 3 must still match.
const idNum = (v) => {
  const m = /^0*(\d+)$/.exec(String(v == null ? '' : v).trim());
  return m ? Number(m[1]) : null;
};
const sameId = (a, b) => idNum(a) !== null && idNum(a) === idNum(b);

// Only an explicit denial deactivates. Blank counts as active, the same way
// the clock and the dashboard read the column.
const inactive = (cell) =>
  ['false', 'no', 'n', '0', 'inactive', 'left'].includes(norm(cell));

// Four digits, and a leading zero is fine: PINs are written as text ('0482),
// and one typed into the sheet by hand, which Sheets keeps as the number 482,
// is read back padded. The clock reads the column the same way.
const pinOk = (p) => /^\d{4}$/.test(p);
const storedPin = (v) => {
  const s = String(v == null ? '' : v).trim();
  return /^\d{1,4}$/.test(s) ? s.padStart(4, '0') : s;
};

const reject = (message) => [{ json: { op: 'reject', message } }];

const action = String(body.action || '').trim();

if (action === 'add') {
  // Written the way the clock pads it, so the sheet never holds '3' beside '003'.
  const id = idNum(body.id) === null ? '' : String(idNum(body.id)).padStart(3, '0');
  const name = String(body.name || '').trim();
  const pin = String(body.pin || '').trim();

  if (!id || !name || !pin) {
    return reject('The request was incomplete — nothing was written.');
  }
  if (!pinOk(pin)) {
    return reject('A PIN is exactly four digits.');
  }

  let highest = 0;
  for (const row of data) {
    const n = idNum(row[0]);
    if (n !== null && n > highest) highest = n;
    if (!String(row[0] || '').trim() && !String(row[1] || '').trim()) continue;

    if (norm(row[1]) === norm(name)) {
      return reject(String(row[1]).trim() + ' is already on the roster.');
    }
    if (storedPin(row[3]) === pin) {
      return reject('That PIN already belongs to someone else. Choose another.');
    }
  }

  // Never reuse a number, even one freed by a deleted row: the QR codes
  // already printed carry the id, so a recycled one would clock the new person
  // in whenever the old card was scanned.
  if (idNum(id) <= highest) {
    return reject(
      id + ' is already taken — somebody was added a moment ago. Reload and try again.',
    );
  }

  return [{ json: {
    op: 'add',
    url: base + range('A:E') + ':append',
    // The apostrophe keeps '003' as text; Sheets would otherwise store 3.
    // 5 is the A&O daily target, written so the row reads like every other.
    values: [["'" + id, name, '5', "'" + pin, 'TRUE']],
    message: name + ' was added as ' + id + '. They can clock in with their PIN now.',
  } }];
}

if (action === 'edit') {
  const id = String(body.id || '').trim();
  const name = String(body.name || '').trim();
  const rawPin = body.pin === undefined || body.pin === null ? '' : String(body.pin).trim();

  let found = -1;
  for (let i = 0; i < data.length; i += 1) {
    if (sameId(data[i][0], id)) { found = i; break; }
  }
  if (found === -1) return reject(id + ' is not on the roster.');

  // Re-sending the PIN somebody already has is not a change. The dashboard
  // never sees PINs, so it cannot tell; the sheet can.
  const pin = rawPin === '' || rawPin === storedPin(data[found][3]) ? null : rawPin;

  if (!name) return reject('The request was incomplete — nothing was written.');
  if (pin !== null && !pinOk(pin)) {
    return reject('A PIN is exactly four digits.');
  }

  // Uniqueness against every OTHER row. Keeping your own name or PIN while
  // changing the other must not be refused as a duplicate of yourself.
  for (let i = 0; i < data.length; i += 1) {
    if (i === found) continue;
    const other = data[i];
    if (!String(other[0] || '').trim() && !String(other[1] || '').trim()) continue;
    if (norm(other[1]) === norm(name)) {
      return reject(String(other[1]).trim() + ' already has that name.');
    }
    if (pin !== null && String(other[3] || '').trim() === pin) {
      return reject('That PIN already belongs to someone else. Choose another.');
    }
  }

  const row = data[found];
  // The name to search the log for comes from the sheet, never from the
  // request. These are payroll rows; what selects them has to come from the
  // same read that found the person.
  const oldName = String(row[1] || '').trim();
  const sheetRow = found + 2;

  const updates = [{ range: 'Employees!B' + sheetRow, values: [[name]] }];
  if (pin !== null) {
    updates.push({ range: 'Employees!D' + sheetRow, values: [["'" + pin]] });
  }

  // A rename has to carry the history with it. Sheet1 records the employee's
  // name, so leaving those rows behind would orphan every shift the person
  // worked. Exact comparison, because the clock matches open shifts exactly:
  // even a change of capitalisation would otherwise strand tonight's row.
  let moved = 0;
  const renamed = oldName !== name;
  if (renamed && oldName) {
    const log = $('Read Time Log').first().json.values || [];
    for (let i = 1; i < log.length; i += 1) {
      const entry = log[i] || [];
      if (norm(entry[1]) === norm(oldName)) {
        updates.push({ range: 'Sheet1!B' + (i + 1), values: [[name]] });
        moved += 1;
      }
    }

    // The clock finds a person's pivot columns by the name in Sheet2's
    // headers, so leaving those behind would start the renamed person a
    // second, empty block and strand their history under the old name.
    const colLetter = (i) => {
      let s = '';
      for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) {
        s = String.fromCharCode(65 + ((n - 1) % 26)) + s;
      }
      return s;
    };
    const pivot = $('Read Pivot Header').first().json.values || [];
    const nameRow = pivot[0] || [];
    const labelRow = pivot[1] || [];
    for (let c = 1; c < nameRow.length; c += 1) {
      if (norm(nameRow[c]) === norm(oldName)) {
        updates.push({ range: 'Sheet2!' + colLetter(c) + '1', values: [[name]] });
      }
    }
    for (let c = 1; c < labelRow.length; c += 1) {
      if (norm(labelRow[c]) === 'total hours of ' + norm(oldName)) {
        updates.push({ range: 'Sheet2!' + colLetter(c) + '2', values: [['Total Hours of ' + name]] });
      }
    }
  }

  if (!renamed && pin === null) {
    return reject('Nothing about ' + oldName + ' has changed.');
  }

  let message;
  if (renamed) {
    message = oldName + ' is now ' + name + '.'
      + (moved > 0
          ? ' ' + moved + ' shift' + (moved === 1 ? '' : 's') + ' moved with them.'
          : ' No shifts were on record under the old name.');
  } else {
    message = name + ' was updated.';
  }
  if (pin !== null) message += ' Their PIN was changed.';

  return [{ json: { op: 'edit', body: { valueInputOption: 'USER_ENTERED', data: updates }, message } }];
}

if (action === 'setActive') {
  const id = String(body.id || '').trim();
  const active = body.active === true;

  let found = -1;
  for (let i = 0; i < data.length; i += 1) {
    if (sameId(data[i][0], id)) { found = i; break; }
  }
  if (found === -1) return reject(id + ' is not on the roster.');

  const row = data[found];
  const who = String(row[1] || id).trim();

  if (!inactive(row[4]) === active) {
    return reject(who + ' is already ' + (active ? 'active' : 'deactivated') + '.');
  }

  // +2, not +1: index 0 is sheet row 2, because row 1 is the header.
  const cell = 'E' + (found + 2);

  return [{ json: {
    op: 'set',
    url: base + range(cell),
    values: [[active ? 'TRUE' : 'FALSE']],
    message: active
      ? who + ' is on the roster again.'
      : who + ' was deactivated. Their shifts are untouched.',
  } }];
}

return reject('Unknown action "' + action + '".');
